package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.SoulFluxNetwork;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class SoulFluxMeterBlock extends PassiveDirectionalSignalBlock{public SoulFluxMeterBlock(Properties p){super(p);}@Override public MapCodec<SoulFluxMeterBlock> codec(){return RedstoneEngineering.SOUL_FLUX_METER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return Math.min(15,(SoulFluxNetwork.charge(l,inputPos(p,s))*15)/100);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,20);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){updateOutput(l,p,s,outputValue(l,p,s));l.scheduleTick(p,this,20);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Soul Flux meter Q="+SoulFluxNetwork.charge(l,inputPos(p,s))+"/100"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}